"""Core :class:`Table` structure and CSV loading/serialization.

The public entry point is :class:`Table`, an immutable-ish container of
column names plus row mappings. Loading from CSV performs lightweight type
inference so that numeric and boolean columns can be analyzed directly.
"""

from __future__ import annotations

import csv
from pathlib import Path
from typing import Any, Callable, Iterable, Iterator, Mapping, Sequence, TextIO

from . import analysis as _analysis
from . import cleaners as _cleaners

DEFAULT_MISSING_VALUES = (
    "",
    "na",
    "n/a",
    "null",
    "none",
    "nan",
    "-",
)

_TRUE_VALUES = {"true", "yes"}
_FALSE_VALUES = {"false", "no"}


def _infer_scalar(text: str) -> Any:
    """Infer int/float/bool from a stripped string, falling back to str."""
    lowered = text.lower()
    if lowered in _TRUE_VALUES:
        return True
    if lowered in _FALSE_VALUES:
        return False
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        pass
    return text


def _coerce_cell(value: Any, infer_types: bool, missing_values: set[str]) -> Any:
    if value is None:
        return None
    stripped = value.strip()
    if stripped.lower() in missing_values:
        return None
    if infer_types:
        return _infer_scalar(stripped)
    return value


def _format_cell(value: Any) -> Any:
    if value is None:
        return ""
    return value


def is_number(value: Any) -> bool:
    """True for int/float but not bool (booleans are treated as categorical)."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


class Table:
    """A column-oriented table backed by a list of row mappings."""

    def __init__(
        self,
        columns: Sequence[str],
        rows: Iterable[Mapping[str, Any]],
    ) -> None:
        self.columns: list[str] = list(columns)
        self._rows: list[dict[str, Any]] = [
            {col: row.get(col) for col in self.columns} for row in rows
        ]

    # ------------------------------------------------------------------
    # Construction / serialization
    # ------------------------------------------------------------------
    @classmethod
    def from_csv(
        cls,
        source: str | Path | TextIO,
        *,
        delimiter: str = ",",
        encoding: str = "utf-8",
        infer_types: bool = True,
        missing_values: Iterable[str] | None = None,
    ) -> "Table":
        """Load a CSV file (path or open file object) into a :class:`Table`."""
        missing = (
            set(DEFAULT_MISSING_VALUES)
            if missing_values is None
            else {m.lower() for m in missing_values}
        )

        close = False
        if isinstance(source, (str, Path)):
            handle: TextIO = open(source, newline="", encoding=encoding)
            close = True
        else:
            handle = source

        try:
            reader = csv.DictReader(handle, delimiter=delimiter)
            columns = list(reader.fieldnames or [])
            rows = [
                {col: _coerce_cell(raw.get(col), infer_types, missing) for col in columns}
                for raw in reader
            ]
        finally:
            if close:
                handle.close()

        return cls(columns, rows)

    @classmethod
    def from_dict(
        cls,
        data: Mapping[str, Sequence[Any]],
    ) -> "Table":
        """Build a table from a mapping of column name to values."""
        columns = list(data)
        lengths = {len(values) for values in data.values()}
        if len(lengths) > 1:
            raise ValueError("all columns must have the same length")
        size = lengths.pop() if lengths else 0
        rows = [
            {col: data[col][i] for col in columns}
            for i in range(size)
        ]
        return cls(columns, rows)

    @classmethod
    def from_records(
        cls,
        records: Iterable[Mapping[str, Any]],
        *,
        columns: Sequence[str] | None = None,
    ) -> "Table":
        """Build a table from an iterable of row mappings."""
        records = list(records)
        if columns is None:
            seen: list[str] = []
            for record in records:
                for key in record:
                    if key not in seen:
                        seen.append(key)
            columns = seen
        return cls(columns, records)

    def to_csv(
        self,
        destination: str | Path | TextIO,
        *,
        delimiter: str = ",",
        encoding: str = "utf-8",
        write_header: bool = True,
    ) -> None:
        """Write the table to a CSV file (path or open file object)."""
        close = False
        if isinstance(destination, (str, Path)):
            handle: TextIO = open(destination, "w", newline="", encoding=encoding)
            close = True
        else:
            handle = destination

        try:
            writer = csv.DictWriter(handle, fieldnames=self.columns, delimiter=delimiter)
            if write_header:
                writer.writeheader()
            for row in self._rows:
                writer.writerow({col: _format_cell(row.get(col)) for col in self.columns})
        finally:
            if close:
                handle.close()

    def to_records(self) -> list[dict[str, Any]]:
        """Return a copy of the rows as a list of dictionaries."""
        return [dict(row) for row in self._rows]

    def to_dict(self) -> dict[str, list[Any]]:
        """Return a copy of the data as a mapping of column name to values."""
        return {col: [row.get(col) for row in self._rows] for col in self.columns}

    # ------------------------------------------------------------------
    # Basic access
    # ------------------------------------------------------------------
    @property
    def rows(self) -> list[dict[str, Any]]:
        return [dict(row) for row in self._rows]

    def __len__(self) -> int:
        return len(self._rows)

    def __iter__(self) -> Iterator[dict[str, Any]]:
        for row in self._rows:
            yield dict(row)

    def __getitem__(self, column: str) -> list[Any]:
        if column not in self.columns:
            raise KeyError(column)
        return [row.get(column) for row in self._rows]

    def __repr__(self) -> str:
        return f"Table(rows={len(self)}, columns={self.columns!r})"

    def head(self, n: int = 5) -> "Table":
        return Table(self.columns, self._rows[:n])

    def tail(self, n: int = 5) -> "Table":
        return Table(self.columns, self._rows[-n:] if n else [])

    def column(self, name: str) -> list[Any]:
        return self[name]

    def copy(self) -> "Table":
        return Table(self.columns, self._rows)

    def numeric_columns(self) -> list[str]:
        """Columns whose non-missing values are all numbers."""
        result = []
        for col in self.columns:
            values = [v for v in self[col] if v is not None]
            if values and all(is_number(v) for v in values):
                result.append(col)
        return result

    def categorical_columns(self) -> list[str]:
        return [col for col in self.columns if col not in self.numeric_columns()]

    # ------------------------------------------------------------------
    # Cleaning (delegates to :mod:`csvlab.cleaners`)
    # ------------------------------------------------------------------
    def drop_duplicates(self, subset: Sequence[str] | None = None) -> "Table":
        return _cleaners.drop_duplicates(self, subset)

    def drop_missing(
        self,
        *,
        how: str = "any",
        subset: Sequence[str] | None = None,
        threshold: float | None = None,
    ) -> "Table":
        return _cleaners.drop_missing(self, how=how, subset=subset, threshold=threshold)

    def fill_missing(
        self,
        value: Any = None,
        *,
        columns: Sequence[str] | None = None,
        strategy: str | None = None,
    ) -> "Table":
        return _cleaners.fill_missing(self, value, columns=columns, strategy=strategy)

    def strip_whitespace(self, columns: Sequence[str] | None = None) -> "Table":
        return _cleaners.strip_whitespace(self, columns)

    def rename_columns(self, mapping: Mapping[str, str]) -> "Table":
        return _cleaners.rename_columns(self, mapping)

    def normalize_headers(self) -> "Table":
        return _cleaners.normalize_headers(self)

    def cast_column(self, column: str, dtype: str) -> "Table":
        return _cleaners.cast_column(self, column, dtype)

    def replace_values(self, column: str, replacements: Mapping[Any, Any]) -> "Table":
        return _cleaners.replace_values(self, column, replacements)

    # ------------------------------------------------------------------
    # Analysis (delegates to :mod:`csvlab.analysis`)
    # ------------------------------------------------------------------
    def describe(self) -> dict[str, dict[str, Any]]:
        return _analysis.describe(self)

    def value_counts(
        self,
        column: str,
        *,
        top: int | None = None,
    ) -> list[tuple[Any, int]]:
        return _analysis.value_counts(self, column, top=top)

    def mean(self, column: str) -> float:
        return _analysis.mean(self, column)

    def median(self, column: str) -> float:
        return _analysis.median(self, column)

    def stdev(self, column: str) -> float:
        return _analysis.stdev(self, column)

    def correlation(self, column_a: str, column_b: str) -> float:
        return _analysis.correlation(self, column_a, column_b)

    def group_by(self, keys: Sequence[str]) -> dict[tuple, "Table"]:
        return _analysis.group_by(self, keys)

    def aggregate(
        self,
        by: Sequence[str],
        aggregations: Mapping[str, str | Callable[[list[Any]], Any]],
    ) -> "Table":
        return _analysis.aggregate(self, by, aggregations)

"""Cleaning operations for :class:`csvlab.table.Table`.

Every function returns a new table and never mutates its input.
"""

from __future__ import annotations

from typing import Any, Iterable, Mapping, Sequence

from .table import is_number

_FORWARD = {"forward", "ffill"}
_BACKWARD = {"backward", "bfill"}
_VALID_STRATEGIES = {
    "mean",
    "median",
    "mode",
    "zero",
    "min",
    "max",
    *_FORWARD,
    *_BACKWARD,
}


def _new(table: Any, rows: Iterable[Mapping[str, Any]]) -> Any:
    return table.__class__(table.columns, rows)


def _resolve_columns(table: Any, columns: Sequence[str] | None) -> list[str]:
    if columns is None:
        return list(table.columns)
    resolved = list(columns)
    unknown = [c for c in resolved if c not in table.columns]
    if unknown:
        raise KeyError(f"unknown columns: {unknown}")
    return resolved


def drop_duplicates(table: Any, subset: Sequence[str] | None = None) -> Any:
    """Remove rows whose values in ``subset`` (default: all columns) repeat."""
    subset = _resolve_columns(table, subset)
    seen: set[tuple] = set()
    rows = []
    for row in table.rows:
        key = tuple(row.get(col) for col in subset)
        if key in seen:
            continue
        seen.add(key)
        rows.append(row)
    return _new(table, rows)


def drop_missing(
    table: Any,
    *,
    how: str = "any",
    subset: Sequence[str] | None = None,
    threshold: float | None = None,
) -> Any:
    """Drop rows containing missing values.

    ``how="any"`` drops a row if any selected column is missing, ``"all"``
    only if every selected column is missing. Alternatively ``threshold``
    (0..1) keeps rows whose missing fraction is at most that value.
    """
    subset = _resolve_columns(table, subset)
    if how not in ("any", "all"):
        raise ValueError("how must be 'any' or 'all'")

    rows = []
    for row in table.rows:
        missing = sum(1 for col in subset if row.get(col) is None)
        if threshold is not None:
            fraction = missing / len(subset) if subset else 0.0
            if fraction <= threshold:
                rows.append(row)
        elif how == "any":
            if missing == 0:
                rows.append(row)
        else:  # all
            if missing < len(subset):
                rows.append(row)
    return _new(table, rows)


def _strategy_value(present: list[Any], strategy: str) -> Any:
    from statistics import mean as _mean, median as _median

    if strategy == "mean":
        return _mean(present)
    if strategy == "median":
        return _median(present)
    if strategy == "min":
        return min(present)
    if strategy == "max":
        return max(present)
    if strategy == "zero":
        return 0
    if strategy == "mode":
        counts: dict[Any, int] = {}
        for value in present:
            counts[value] = counts.get(value, 0) + 1
        return max(counts, key=counts.get)
    raise ValueError(f"unknown fill strategy: {strategy!r}")


def fill_missing(
    table: Any,
    value: Any = None,
    *,
    columns: Sequence[str] | None = None,
    strategy: str | None = None,
) -> Any:
    """Fill missing values with ``value`` or a computed ``strategy``.

    Supported strategies: mean, median, mode, min, max, zero, forward,
    backward. Mean/median/min/max are skipped for non-numeric columns.
    """
    if strategy is not None and strategy not in _VALID_STRATEGIES:
        raise ValueError(f"unknown fill strategy: {strategy!r}")
    if value is None and strategy is None:
        raise ValueError("provide either value or strategy")

    resolved = _resolve_columns(table, columns)
    rows = [dict(row) for row in table.rows]

    for col in resolved:
        present = [row.get(col) for row in rows if row.get(col) is not None]

        if strategy in _FORWARD or strategy in _BACKWARD:
            ordered = rows if strategy in _FORWARD else list(reversed(rows))
            carry = None
            for row in ordered:
                current = row.get(col)
                if current is None:
                    row[col] = carry
                else:
                    carry = current
            continue

        if strategy in ("mean", "median", "min", "max"):
            numeric = [v for v in present if is_number(v)]
            if not numeric:
                continue
            fill = _strategy_value(numeric, strategy)
        elif strategy is not None:
            if not present:
                continue
            fill = _strategy_value(present, strategy)
        else:
            fill = value

        for row in rows:
            if row.get(col) is None:
                row[col] = fill

    return _new(table, rows)


def strip_whitespace(table: Any, columns: Sequence[str] | None = None) -> Any:
    """Trim surrounding whitespace from string values."""
    resolved = _resolve_columns(table, columns)
    rows = [dict(row) for row in table.rows]
    for row in rows:
        for col in resolved:
            value = row.get(col)
            if isinstance(value, str):
                row[col] = value.strip()
    return _new(table, rows)


def rename_columns(table: Any, mapping: Mapping[str, str]) -> Any:
    """Rename columns; unknown source names raise :class:`KeyError`."""
    unknown = [src for src in mapping if src not in table.columns]
    if unknown:
        raise KeyError(f"unknown columns: {unknown}")
    columns = [mapping.get(col, col) for col in table.columns]
    if len(set(columns)) != len(columns):
        raise ValueError("renaming would produce duplicate column names")
    rows = [
        {mapping.get(col, col): value for col, value in row.items()}
        for row in table.rows
    ]
    return _new(table, rows)


def _normalize_name(name: str) -> str:
    cleaned = "".join(ch.lower() if ch.isalnum() else "_" for ch in name.strip())
    while "__" in cleaned:
        cleaned = cleaned.replace("__", "_")
    return cleaned.strip("_")


def normalize_headers(table: Any) -> Any:
    """Lowercase headers and replace non-alphanumeric characters with ``_``."""
    columns = [_normalize_name(col) for col in table.columns]
    if len(set(columns)) != len(columns):
        raise ValueError("normalizing headers would produce duplicate names")
    rows = [
        {_normalize_name(col): value for col, value in row.items()}
        for row in table.rows
    ]
    return _new(table, rows)


def cast_column(table: Any, column: str, dtype: str) -> Any:
    """Cast a column to ``"int"``, ``"float"``, ``"str"``, or ``"bool"``.

    Missing values are preserved and unparseable values raise :class:`ValueError`.
    """
    if column not in table.columns:
        raise KeyError(column)
    caster = _CASTERS.get(dtype)
    if caster is None:
        raise ValueError(f"unknown dtype: {dtype!r}")

    rows = []
    for row in table.rows:
        row = dict(row)
        value = row.get(column)
        if value is not None:
            try:
                row[column] = caster(value)
            except (TypeError, ValueError) as exc:
                raise ValueError(
                    f"cannot convert {value!r} in column {column!r} to {dtype}"
                ) from exc
        rows.append(row)
    return _new(table, rows)


def _to_bool(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    text = str(value).strip().lower()
    if text in {"true", "yes", "1"}:
        return True
    if text in {"false", "no", "0"}:
        return False
    raise ValueError(value)


_CASTERS = {
    "int": int,
    "float": float,
    "str": str,
    "bool": _to_bool,
}


def replace_values(table: Any, column: str, replacements: Mapping[Any, Any]) -> Any:
    """Replace specific values within a column."""
    if column not in table.columns:
        raise KeyError(column)
    rows = []
    for row in table.rows:
        row = dict(row)
        value = row.get(column)
        if value in replacements:
            row[column] = replacements[value]
        rows.append(row)
    return _new(table, rows)

"""Analysis helpers for :class:`csvlab.table.Table`."""

from __future__ import annotations

from statistics import mean as _mean, median as _median, pstdev, stdev as _stdev
from typing import Any, Callable, Iterable, Mapping, Sequence

from .table import is_number


def _new(table: Any, columns: Sequence[str], rows: Iterable[Mapping[str, Any]]) -> Any:
    return table.__class__(columns, rows)


def _numeric_values(table: Any, column: str) -> list[Any]:
    if column not in table.columns:
        raise KeyError(column)
    return [v for v in table[column] if is_number(v)]


def _require_numeric(table: Any, column: str) -> list[Any]:
    values = _numeric_values(table, column)
    if not values:
        raise TypeError(f"column {column!r} has no numeric values")
    return values


def _quantile(sorted_values: Sequence[float], q: float) -> float:
    if len(sorted_values) == 1:
        return float(sorted_values[0])
    position = (len(sorted_values) - 1) * q
    lower = int(position)
    upper = min(lower + 1, len(sorted_values) - 1)
    fraction = position - lower
    return sorted_values[lower] * (1 - fraction) + sorted_values[upper] * fraction


def describe(table: Any) -> dict[str, dict[str, Any]]:
    """Return per-column summary statistics.

    Numeric columns report count/missing/mean/std/quartiles; other columns
    report count/missing/unique/most-common value and its frequency.
    """
    summary: dict[str, dict[str, Any]] = {}
    for col in table.columns:
        values = table[col]
        present = [v for v in values if v is not None]
        missing = len(values) - len(present)
        numeric = present and all(is_number(v) for v in present)

        if numeric:
            ordered = sorted(present)
            summary[col] = {
                "count": len(present),
                "missing": missing,
                "mean": _mean(present),
                "std": pstdev(present) if len(present) > 1 else 0.0,
                "min": ordered[0],
                "q1": _quantile(ordered, 0.25),
                "median": _median(present),
                "q3": _quantile(ordered, 0.75),
                "max": ordered[-1],
                "sum": sum(present),
            }
        else:
            counts: dict[Any, int] = {}
            for value in present:
                counts[value] = counts.get(value, 0) + 1
            top_value, top_count = (None, 0)
            if counts:
                top_value = max(counts, key=counts.get)
                top_count = counts[top_value]
            summary[col] = {
                "count": len(present),
                "missing": missing,
                "unique": len(counts),
                "top": top_value,
                "freq": top_count,
            }
    return summary


def value_counts(
    table: Any,
    column: str,
    *,
    top: int | None = None,
) -> list[tuple[Any, int]]:
    """Return ``(value, count)`` pairs sorted by descending frequency."""
    if column not in table.columns:
        raise KeyError(column)
    counts: dict[Any, int] = {}
    for value in table[column]:
        if value is not None:
            counts[value] = counts.get(value, 0) + 1
    ordered = sorted(counts.items(), key=lambda item: item[1], reverse=True)
    if top is not None:
        ordered = ordered[:top]
    return ordered


def mean(table: Any, column: str) -> float:
    return _mean(_require_numeric(table, column))


def median(table: Any, column: str) -> float:
    return _median(_require_numeric(table, column))


def stdev(table: Any, column: str) -> float:
    values = _require_numeric(table, column)
    return _stdev(values) if len(values) > 1 else 0.0


def correlation(table: Any, column_a: str, column_b: str) -> float:
    """Pearson correlation over rows where both columns are numeric."""
    pairs = [
        (row.get(column_a), row.get(column_b))
        for row in table.rows
        if is_number(row.get(column_a)) and is_number(row.get(column_b))
    ]
    if len(pairs) < 2:
        raise ValueError("correlation requires at least two paired numeric values")
    xs = [pair[0] for pair in pairs]
    ys = [pair[1] for pair in pairs]
    mean_x, mean_y = _mean(xs), _mean(ys)
    covariance = sum((x - mean_x) * (y - mean_y) for x, y in pairs)
    var_x = sum((x - mean_x) ** 2 for x in xs)
    var_y = sum((y - mean_y) ** 2 for y in ys)
    if var_x == 0 or var_y == 0:
        return 0.0
    return covariance / (var_x**0.5 * var_y**0.5)


def group_by(table: Any, keys: Sequence[str]) -> dict[tuple, Any]:
    """Group rows by one or more columns, returning keyed sub-tables."""
    keys = list(keys)
    unknown = [k for k in keys if k not in table.columns]
    if unknown:
        raise KeyError(f"unknown columns: {unknown}")
    groups: dict[tuple, list[dict[str, Any]]] = {}
    for row in table.rows:
        group_key = tuple(row.get(k) for k in keys)
        groups.setdefault(group_key, []).append(row)
    return {key: _new(table, table.columns, rows) for key, rows in groups.items()}


def _count(values: list[Any]) -> int:
    return len(values)


def _sum(values: list[Any]) -> Any:
    return sum(values) if values else None


def _min(values: list[Any]) -> Any:
    return min(values) if values else None


def _max(values: list[Any]) -> Any:
    return max(values) if values else None


def _first(values: list[Any]) -> Any:
    return values[0] if values else None


def _last(values: list[Any]) -> Any:
    return values[-1] if values else None


def _nunique(values: list[Any]) -> int:
    return len(set(values))


def _mode(values: list[Any]) -> Any:
    if not values:
        return None
    counts: dict[Any, int] = {}
    for value in values:
        counts[value] = counts.get(value, 0) + 1
    return max(counts, key=counts.get)


_AGGREGATORS: dict[str, Callable[[list[Any]], Any]] = {
    "count": _count,
    "sum": _sum,
    "mean": lambda values: _mean(values) if values else None,
    "median": lambda values: _median(values) if values else None,
    "min": _min,
    "max": _max,
    "stdev": lambda values: _stdev(values) if len(values) > 1 else (0.0 if values else None),
    "first": _first,
    "last": _last,
    "nunique": _nunique,
    "mode": _mode,
}


def aggregate(
    table: Any,
    by: Sequence[str],
    aggregations: Mapping[str, str | Callable[[list[Any]], Any]],
) -> Any:
    """Group by ``by`` and apply aggregations, returning a new table.

